/* AUDIT FIX F-15 (v14.90): setelah postTransaksi sukses, allRows/dashboard cache
   tidak pernah di-refresh otomatis -> tab Data/Dashboard bisa tampilkan saldo basi
   sampai user tekan Refresh manual. Fungsi ini melakukan refresh data penuh di
   background (tanpa menyentuh UI tombol/status bar milik tab Data) supaya allRows,
   render tabel, dan cache dashboard (_dashLastLoad) semuanya konsisten dengan saldo
   terbaru begitu transaksi tersimpan. Gagal diam-diam (non-blocking, non-critical) --
   kalau fetch ini gagal, user tetap bisa refresh manual seperti sebelumnya. */
function silentRefreshAfterTransaksi(){
  gasGet({action:'getData'}).then(function(result){
    if(!result||result.status==='error')return;
    allRows=result.rows.map(function(r,i){r._idx=i;return r;});
    syncMinStockMap();
    filteredRows=allRows.slice();
    _applySort();
    renderTable(filteredRows);
    renderCatFilter();
    _dashLastLoad=0;
  }).catch(function(){/* silent: background refresh, jangan ganggu UX scanner */});
}
function loadData(){var btn=document.getElementById('btn-load');btn.disabled=true;btn.innerHTML=IC.load+' Memuat...';showStatus('sbar-load','s-info',IC.load+' Mengambil data dari spreadsheet...');return gasGet({action:'getData'}).then(function(result){btn.disabled=false;btn.innerHTML='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="1 4 1 10 7 10"/><polyline points="23 20 23 14 17 14"/><path d="M20.49 9A9 9 0 005.64 5.64L1 10m22 4l-4.64 4.36A9 9 0 013.51 15"/></svg> Refresh';if(result.status==='error'){showStatus('sbar-load','s-err',IC.err+' '+xe(result.message));return;}
allRows=result.rows.map(function(r,i){r._idx=i;return r;});syncMinStockMap();filteredRows=allRows.slice();_applySort();renderTable(filteredRows);renderCatFilter();document.getElementById('last-load').textContent='Dimuat '+new Date().toLocaleTimeString('id-ID')+' · '+allRows.length+' item';showStatus('sbar-load','s-ok',IC.ok+' Berhasil memuat <strong>'+allRows.length+' item</strong>');}).catch(function(err){btn.disabled=false;btn.innerHTML='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="1 4 1 10 7 10"/><polyline points="23 20 23 14 17 14"/><path d="M20.49 9A9 9 0 005.64 5.64L1 10m22 4l-4.64 4.36A9 9 0 013.51 15"/></svg> Refresh';showStatus('sbar-load','s-err',IC.err+' '+xe(err.message));});}
var INV_PAGE_SIZE=50;var invPage=1;var _invFilteredRows=[];function renderTable(rows){_invFilteredRows=rows;invPage=1;_renderInventoryPage();}
function calcTotalPages(rows,pageSize){return Math.max(1,Math.ceil(rows.length/pageSize));}
