function saveTransaksiDraft(){if(!currentItem)return;try{var qty=document.getElementById('qty-input').value,rak=document.getElementById('rak-input').value,vendor=document.getElementById('vendor-input').value,noref=document.getElementById('noref-input').value,ket=document.getElementById('ket-input').value;var prev=null;try{prev=JSON.parse(localStorage.getItem('rdi_trx_draft')||'null');}catch(e){}
var sameIntent=prev&&prev.itemId===currentItem.id&&prev.jenis===currentJenis&&String(prev.qty)===String(qty)&&String(prev.rak)===String(rak)&&String(prev.vendor)===String(vendor)&&String(prev.noref)===String(noref)&&String(prev.ket)===String(ket);if(!sameIntent||!currentRequestId)currentRequestId=genRequestId();localStorage.setItem('rdi_trx_draft',JSON.stringify({itemId:currentItem.id,nama:currentItem.nama,jenis:currentJenis,qty:qty,rak:rak,vendor:vendor,noref:noref,ket:ket,requestId:currentRequestId,savedAt:Date.now()}));}catch(e){}}
function clearTransaksiDraft(){try{localStorage.removeItem('rdi_trx_draft');}catch(e){}currentRequestId=null;}
function checkTransaksiDraft(){var raw;try{raw=localStorage.getItem('rdi_trx_draft');}catch(e){return;}
if(!raw)return;var d;try{d=JSON.parse(raw);}catch(e){clearTransaksiDraft();return;}
if(!d||!d.itemId||(Date.now()-d.savedAt)>2*60*60*1000){clearTransaksiDraft();return;}
var box=document.createElement('div');box.style.cssText='position:fixed;left:12px;right:12px;bottom:80px;z-index:600;background:var(--amber-dim);border:1px solid var(--amber-border);border-radius:var(--r);padding:var(--sp-12) var(--sp-14);box-shadow:var(--shadow-lg)';box.innerHTML='<div style="font-size:12px;color:var(--text);margin-bottom:8px">⏳ Ada transaksi belum selesai: <strong>'+xe(d.nama)+'</strong> ('+xe(d.jenis)+' '+xe(d.qty)+')</div>'
+'<div style="display:flex;gap:var(--space-1)">'
+'<button class="btn btn-primary btn-sm u-flex-1" id="draft-resume-btn">Lanjutkan</button>'
+'<button class="btn btn-sm u-flex-1" id="draft-discard-btn">Buang</button>'
+'</div>';document.body.appendChild(box);document.getElementById('draft-resume-btn').onclick=function(){switchTab('scanner');gasGet({action:'getItem',id:d.itemId}).then(function(res){if(res.status==='ok'){currentItem=res.item;populatePreview(currentItem);currentJenis=d.jenis;setJenis(d.jenis);document.getElementById('qty-input').value=d.qty;document.getElementById('rak-input').value=d.rak;document.getElementById('vendor-input').value=d.vendor;document.getElementById('noref-input').value=d.noref;document.getElementById('ket-input').value=d.ket;currentRequestId=d.requestId||genRequestId();updateSaldoPreview();checkTransactionAnomaly();markRakChipSelection();showScanStep('transaksi');}
box.remove();}).catch(function(){box.remove();});};document.getElementById('draft-discard-btn').onclick=function(){clearTransaksiDraft();box.remove();};}
function lookupItem(){acHide('scan');var raw=document.getElementById('scan-id-input').value.trim().toUpperCase();if(!raw){showStatus('sbar-lookup','s-warn',IC.info+' Masukkan ID item');return;}
var id=raw;if(allRows.length){var exactRow=allRows.find(function(r){return(r.id||'').toUpperCase()===raw;});if(!exactRow){var best=null,bestScore=0;allRows.forEach(function(r){var res=fuzzyMatch(r,raw.toLowerCase());if(res.match&&res.score>bestScore){bestScore=res.score;best=r;}});if(best&&best.id)id=best.id.toUpperCase();exactRow=best;}
if(exactRow&&_isArsip(exactRow)&&scanMode!=='cekstok'){showStatus('sbar-lookup','s-warn',IC.info+' Item ini sudah diarsipkan dan tidak bisa ditransaksikan. Aktifkan kembali dulu dari halaman detail item.');return;}}
document.getElementById('scan-id-input').value=id;var btn=document.getElementById('btn-lookup');btn.disabled=true;btn.innerHTML=IC.load+' Mencari...';showStatus('sbar-lookup','s-info',IC.load+' Mencari <strong>'+xe(id)+'</strong>...');gasGet({action:'getItem',id:id}).then(function(result){btn.disabled=false;btn.innerHTML='Cari';if(result.status==='error'){showStatus('sbar-lookup','s-err',IC.err+' '+xe(result.message));return;}
currentItem=result.item;currentRequestId=null;hideStatus('sbar-lookup');if(scanMode==='cekstok'){populateCekStok(result.item);showScanStep('cekstok');return;}
populatePreview(result.item);currentJenis=null;setJenis(null);document.getElementById('qty-input').value=1;document.getElementById('ket-input').value='';document.getElementById('vendor-input').value='';document.getElementById('noref-input').value='';updateSaldoPreview();checkTransactionAnomaly();hideStatus('sbar-submit');showScanStep('transaksi');setTimeout(function(){var qtyEl=document.getElementById('qty-input');if(qtyEl){qtyEl.focus();qtyEl.select();}},50);}).catch(function(err){btn.disabled=false;btn.innerHTML='Cari';showStatus('sbar-lookup','s-err',IC.err+' '+xe(err.message));});}
function populatePreview(item){document.getElementById('preview-id').textContent=item.id||'—';document.getElementById('preview-nama').textContent=item.nama||'—';document.getElementById('preview-spec').textContent=item.spec||'—';document.getElementById('preview-rak').textContent=formatRakBreakdown(item.rakBreakdown);document.getElementById('preview-vendor').textContent='Lihat riwayat transaksi';document.getElementById('preview-user').textContent=item.user||'—';document.getElementById('preview-unit').textContent=item.unit||'—';document.getElementById('preview-unit2').textContent=item.unit||'—';document.getElementById('preview-saldo').textContent=item.saldo!=null?item.saldo:'—';var rakInput=document.getElementById('rak-input');var rakDl=document.getElementById('dl-rak-item');if(rakInput&&item.rakBreakdown&&item.rakBreakdown.length){var sorted=item.rakBreakdown.slice().sort(function(a,b){return b.qty-a.qty;});rakInput.value=sorted[0].rak;if(rakDl)rakDl.innerHTML=sorted.map(function(r){return'<option value="'+xe(r.rak)+'">';}).join('');rakInput.setAttribute('list','dl-rak-item');}else if(rakInput){rakInput.value='';rakInput.setAttribute('list','dl-rak');}
renderRakChips(item.rakBreakdown);updateSaldoPreview();checkTransactionAnomaly();}
function renderRakChips(rakBreakdown){var box=document.getElementById('rak-chips');if(!box)return;if(!rakBreakdown||!rakBreakdown.length){box.innerHTML='';return;}
var sorted=rakBreakdown.slice().sort(function(a,b){return b.qty-a.qty;});box.innerHTML=sorted.map(function(r){return'<button type="button" class="rak-chip" onclick="selectRakChip(\''+xeJs(r.rak)+'\')">'+xe(r.rak)+' · '+xe(r.qty)+'</button>';}).join('');markRakChipSelection();}
function selectRakChip(rak){var rakInput=document.getElementById('rak-input');if(rakInput){rakInput.value=(rak||'').toUpperCase();saveTransaksiDraft();}
markRakChipSelection();}
function markRakChipSelection(){var val=(document.getElementById('rak-input')||{}).value||'';document.querySelectorAll('#rak-chips .rak-chip').forEach(function(chip){chip.classList.toggle('selected',chip.textContent.split(' · ')[0].toUpperCase()===val.toUpperCase());});}
function updateSaldoPreview(){var el=document.getElementById('preview-saldo-after');if(!el||!currentItem)return;if(!currentJenis){el.textContent='—';el.className='saldo-after-val';return;}
var saldo=parseFloat(currentItem.saldo)||0;var qty=parseFloat((document.getElementById('qty-input')||{}).value)||0;var after=currentJenis==='KELUAR'?(saldo-qty):(saldo+qty);var unit=currentItem.unit||'';el.textContent=after+' '+unit;el.className='saldo-after-val '+(after<0?'warn':(currentJenis==='KELUAR'?'down':'up'));}
function formatRakBreakdown(list){if(!list||!list.length)return'Belum ada stok di rak manapun';return list.map(function(r){return r.rak+': '+r.qty;}).join(', ');}
function setJenis(jenis){currentJenis=jenis;document.getElementById('btn-masuk').className='jenis-btn'+(jenis==='MASUK'?' active-masuk':'');document.getElementById('btn-keluar').className='jenis-btn'+(jenis==='KELUAR'?' active-keluar':'');var card=document.getElementById('item-preview');if(card)card.className='item-card '+(jenis==='KELUAR'?'jenis-keluar':(jenis==='MASUK'?'jenis-masuk':''));var subBtn=document.getElementById('btn-submit');if(subBtn)subBtn.disabled=!jenis;updateSaldoPreview();checkTransactionAnomaly();}
function adjustQty(delta){var inp=document.getElementById('qty-input');inp.value=Math.max(1,(parseInt(inp.value)||0)+delta);saveTransaksiDraft();updateSaldoPreview();checkTransactionAnomaly();}
var _anomalyStats={itemId:null,avg:0,median:0,maxQty:0,loaded:false};function checkTransactionAnomaly(){if(!currentItem||!currentItem.id){hideAnomalyWarning();return;}
var itemId=currentItem.id;if(_anomalyStats.itemId!==itemId||!_anomalyStats.loaded){hideAnomalyWarning();_anomalyStats={itemId:itemId,avg:0,median:0,maxQty:0,loaded:false};gasGet({action:'getLedger',id:itemId}).then(function(res){if(!currentItem||currentItem.id!==itemId)return;if(!res||res.status!=='ok'){_anomalyStats.loaded=true;return;}
var qtys=(res.entries||[]).map(function(e){return parseFloat(e.qty)||0;}).filter(function(q){return q>0;});if(qtys.length){var sum=0;qtys.forEach(function(q){sum+=q;});_anomalyStats.avg=sum/qtys.length;var sorted=qtys.slice().sort(function(a,b){return a-b;});var mid=Math.floor(sorted.length/2);_anomalyStats.median=sorted.length%2?sorted[mid]:(sorted[mid-1]+sorted[mid])/2;_anomalyStats.maxQty=sorted[sorted.length-1];}
_anomalyStats.loaded=true;evaluateAnomalyWarning();}).catch(function(){if(_anomalyStats.itemId===itemId)_anomalyStats.loaded=true;});return;}
evaluateAnomalyWarning();}
function evaluateAnomalyWarning(){var el=document.getElementById('qty-anomaly-warning');if(!el)return;if(!_anomalyStats.loaded||_anomalyStats.maxQty<=0){el.style.display='none';return;}
var qty=parseFloat(document.getElementById('qty-input').value)||0;if(qty<=0){el.style.display='none';return;}
var isAnomaly=(qty>3*_anomalyStats.avg)||(qty>_anomalyStats.maxQty);if(!isAnomaly){el.style.display='none';return;}
el.innerHTML='⚠ Qty jauh lebih besar dibanding histori transaksi item ini. '
+'(Rata-rata: '+Math.round(_anomalyStats.avg*10)/10+', Median: '+_anomalyStats.median
+', Terbesar sebelumnya: '+_anomalyStats.maxQty+')';el.style.display='block';}
function hideAnomalyWarning(){var el=document.getElementById('qty-anomaly-warning');if(el)el.style.display='none';}
function submitTransaksi(){if(!currentItem){showStatus('sbar-submit','s-err',IC.err+' Tidak ada item');return;}
if(!currentJenis){showStatus('sbar-submit','s-warn',IC.info+' Pilih jenis transaksi (Masuk / Keluar) terlebih dahulu');return;}
var qty=parseInt(document.getElementById('qty-input').value)||0;if(qty<=0){showStatus('sbar-submit','s-warn',IC.info+' Qty harus lebih dari 0');flagFieldError('qty-input');return;}
var ket=document.getElementById('ket-input').value.trim();var rak=document.getElementById('rak-input').value.trim().toUpperCase();if(!rak){showStatus('sbar-submit','s-warn',IC.info+' Lokasi RAK wajib diisi');flagFieldError('rak-input');return;}
var vendor=document.getElementById('vendor-input').value.trim();var noRef=document.getElementById('noref-input').value.trim();var btn=document.getElementById('btn-submit');btn.disabled=true;btn.innerHTML=IC.load+' Menyimpan...';showStatus('sbar-submit','s-info',IC.load+' Menyimpan transaksi...');saveTransaksiDraft();var payload={action:'postTransaksi',itemId:currentItem.id,jenis:currentJenis,qty:qty,rak:rak,vendor:vendor,noReferensi:noRef,keterangan:ket,admin:getAdminLabel(),requestId:currentRequestId};gasPost(payload).then(function(result){btn.disabled=false;btn.innerHTML='<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg> Simpan Transaksi';if(result.status==='error'){var isNetworkErr=/^Network error/.test(result.message||'');if(isNetworkErr){showStatus('sbar-submit','s-warn',IC.info+' Status transaksi belum dapat dipastikan (koneksi terputus). JANGAN input transaksi baru untuk data yang sama. Tap Simpan lagi (aman, tidak akan tercatat dobel) atau cek History untuk memastikan.');return;}
showStatus('sbar-submit','s-err',IC.err+' '+xe(result.message));flagFieldError(result.message&&result.message.indexOf('RAK')>-1?'rak-input':'qty-input');return;}
clearTransaksiDraft();registerMasterValueIfNew('rak',rak);registerMasterValueIfNew('vendor',vendor);showResult(result,currentJenis,qty);showScanStep('result');silentRefreshAfterTransaksi();}).catch(function(err){btn.disabled=false;btn.innerHTML='Simpan Transaksi';showStatus('sbar-submit','s-warn',IC.info+' Status transaksi belum dapat dipastikan. JANGAN input ulang -- tap Simpan lagi atau cek History.');});}
function showResult(result,jenis,qty){var isOk=result.status==='ok';var isPartial=result.status==='partial';var cls=isOk?'ok':(isPartial?'partial':'err');document.getElementById('result-card').className='result-card '+cls;document.getElementById('result-icon').className='result-icon '+cls;document.getElementById('result-title').textContent=isOk?'Transaksi Berhasil':(isPartial?'Transaksi Tercatat, Perlu Verifikasi':'Transaksi Gagal');document.getElementById('result-sub').textContent=isOk?(jenis+' '+qty+' '+result.unit+' · '+xe(result.namaItem)):xe(result.message);if(isOk){document.getElementById('result-before').textContent=result.saldoSebelum+' '+result.unit;var afterEl=document.getElementById('result-after');afterEl.textContent=result.saldoSesudah+' '+result.unit;afterEl.className=jenis==='MASUK'?'saldo-after-masuk':'saldo-after-keluar';document.getElementById('result-saldo-change').style.display='flex';}else{document.getElementById('result-saldo-change').style.display='none';}
if(isOk&&currentItem)currentItem.saldo=result.saldoSesudah;}
